        if (obs.t > 13.0 && distH < 0.18) ty = 0.025;

        const vxDes = clamp(2.5 * dxPad, -1.15, 1.15);
        const vzDes = clamp(2.5 * dzPad, -1.15, 1.15);
        axDes = 5.8 * (vxDes - v.x) + 1.6 * clamp(dxPad, -0.10, 0.10);
        azDes = 5.8 * (vzDes - v.z) + 1.6 * clamp(dzPad, -0.10, 0.10);

        const ey = ty - p.y;
