      if (p.x > 2.55 && v.x > 0) axDes = Math.min(axDes, -5.5 * v.x + 4.5 * (2.55 - p.x));
      if (p.z < -2.55 && v.z < 0) azDes = Math.max(azDes, -5.5 * v.z + 4.5 * (-2.55 - p.z));
      if (p.z > 2.55 && v.z > 0) azDes = Math.min(azDes, -5.5 * v.z + 4.5 * (2.55 - p.z));
      if (p.y > 2.65 && v.y > 0) ayDes = Math.min(ayDes, -6.5 * v.y + 5.0 * (2.65 - p.y));

      // Cancel linear drag and observed wind acceleration
      const wCtrlX = wAcc.x + 0.50 * (wFast.x - wAcc.x);
      const wCtrlZ = wAcc.z + 0.50 * (wFast.z - wAcc.z);
      const axThrust = clamp(axDes + cDrag * v.x - wCtrlX, -5.8, 5.8);
      const azThrust = clamp(azDes + cDrag * v.z - wCtrlZ, -5.8, 5.8);
      const ayThrust = clamp(9.81 + ayDes + cDrag * v.y, 1.2, 15.5);

      const dirY = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const thrustCmd = clamp(ayThrust / (thrustScale * dirY), 0.04, 0.78);

      // Desired attitude from desired thrust vector (axThrust, ayThrust, azThrust)
