const GATE_LIST = [
  { x: -1.15, y: 1.05, z: -0.85 },
  { x: 0.15, y: 1.40, z: 0.25 },
  { x: 1.35, y: 1.05, z: 1.05 },
];

export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const hypot2 = (x, z) => Math.hypot(x, z);
  const hypot3 = (x, y, z) => Math.hypot(x, y, z);

  let prevObs = null;
  let lastAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };
  let prevRollDes = 0;
  let prevPitchDes = 0;
  let simInt = { roll: 0, pitch: 0 };
  let uEff = { roll: 0, pitch: 0, yaw: 0 };
  let thrustEff = 0.5;

  // Torque bias observer (per unit thrust + fast residual)
  let kBias = { roll: 0, pitch: 0, yaw: 0 };
  let fastBias = { roll: 0, pitch: 0 };

  // Thrust scale observer: effective (maxThrustSum / mass), nominal ~20.0
  let thrustScale = 20.0;
  let vyHat = 0;

  // Wind acceleration observers (m/s^2)
  let vHat = { x: 0, z: 0 };
  let wAcc = { x: 0, z: 0 };
  let wFast = { x: 0, z: 0 };
  let baseWindAcc = { x: 0, z: 0 };

  // Navigation state
  let targetGate = -1;
  let phase = 'align';
  let centeredCount = 0;
  let padPinned = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos;
      const v = obs.vel;
      const att = obs.att;
      const rates = obs.rates;

      if (prevObs !== null) {
        const alphaLag = 0.23; // ~0.038s motor lag
        for (const axis of ['roll', 'pitch']) {
          const e1 = lastAction[axis] - prevObs.att[axis];
          simInt[axis] = clamp(simInt[axis] + e1 * 0.005, -0.35, 0.35);
          const u1 = 65 * e1 - 13 * prevObs.rates[axis] + 22 * simInt[axis];

          const attMid = 0.5 * (prevObs.att[axis] + att[axis]);
          const rateMid = 0.5 * (prevObs.rates[axis] + rates[axis]);
          const e2 = lastAction[axis] - attMid;
          simInt[axis] = clamp(simInt[axis] + e2 * 0.005, -0.35, 0.35);
          const u2 = 65 * e2 - 13 * rateMid + 22 * simInt[axis];

          const uCmd = 0.5 * (u1 + u2);
          uEff[axis] += (uCmd - uEff[axis]) * alphaLag;
        }
        const uYawCmd = 8 * (lastAction.yawRate - 0.5 * (prevObs.rates.yaw + rates.yaw));
        uEff.yaw += (uYawCmd - uEff.yaw) * alphaLag;
        thrustEff += (lastAction.thrust - thrustEff) * alphaLag;

        const airborne = p.y > 0.085 && prevObs.pos.y > 0.085 && p.y < 2.91;

        if (airborne && thrustEff > 0.12 && thrustEff < 0.82) {
          for (const axis of ['roll', 'pitch']) {
            if (Math.abs(lastAction[axis]) < 0.55) {
              const rateMid = 0.5 * (prevObs.rates[axis] + rates[axis]);
              const alphaMeas = (rates[axis] - prevObs.rates[axis]) / dt + 0.4 * rateMid;
              const res = alphaMeas - uEff[axis];
              const predBias = kBias[axis] * thrustEff;
              const err = clamp(res - predBias, -20, 20);
              const gain = 0.20 * thrustEff / (thrustEff * thrustEff + 0.04);
              kBias[axis] = clamp(kBias[axis] + gain * err, -25, 25);
              fastBias[axis] = clamp(fastBias[axis] + 0.07 * (res - kBias[axis] * thrustEff - fastBias[axis]), -5, 5);
            }
          }
          const rateYawMid = 0.5 * (prevObs.rates.yaw + rates.yaw);
          const alphaYawMeas = (rates.yaw - prevObs.rates.yaw) / dt + 0.4 * rateYawMid;
          const resYaw = alphaYawMeas - uEff.yaw;
          const errYaw = clamp(resYaw - kBias.yaw * thrustEff, -8, 8);
          kBias.yaw = clamp(kBias.yaw + 0.15 * thrustEff * errYaw / (thrustEff * thrustEff + 0.04), -6, 6);
        }

        const attR = 0.5 * (prevObs.att.roll + att.roll);
        const attP = 0.5 * (prevObs.att.pitch + att.pitch);
        const attY = 0.5 * (prevObs.att.yaw + att.yaw);
        const bodyX = Math.sin(attP) * Math.cos(attR);
        const bodyZ = -Math.sin(attR);
        const dirX = Math.cos(attY) * bodyX + Math.sin(attY) * bodyZ;
        const dirY = Math.cos(attP) * Math.cos(attR);
        const dirZ = -Math.sin(attY) * bodyX + Math.cos(attY) * bodyZ;

        if (airborne) {
          const vyMid = 0.5 * (prevObs.vel.y + v.y);
          const uy = thrustEff * dirY - 0.0275 * vyMid;
          const vyPred = vyHat + (thrustScale * uy - 9.81) * dt;
          const errVy = v.y - vyPred;
          vyHat = vyPred + 0.42 * errVy;
          if (uy > 0.15 && thrustEff < 0.82) {
            thrustScale = clamp(thrustScale + 5.0 * errVy * uy, 14.8, 26.8);
          }
        } else {
          vyHat = v.y;
        }

        const clearWalls = Math.abs(p.x) < 2.81 && Math.abs(p.z) < 2.81;
        if (airborne && clearWalls) {
          const cDrag = 0.0275 * thrustScale;
          for (const axis of ['x', 'z']) {
            const dirA = axis === 'x' ? dirX : dirZ;
            const vMid = 0.5 * (prevObs.vel[axis] + v[axis]);
            const aKnown = thrustScale * thrustEff * dirA - cDrag * vMid;
            const vPred = vHat[axis] + (aKnown + wAcc[axis]) * dt;
            const errV = v[axis] - vPred;
            vHat[axis] = vPred + 0.48 * errV;
            wAcc[axis] = clamp(wAcc[axis] + 7.2 * errV, -8.8, 8.8);

            const aMeas = (v[axis] - prevObs.vel[axis]) / dt;
            const wInst = clamp(aMeas - aKnown, -10.5, 10.5);
            wFast[axis] += 0.48 * (wInst - wFast[axis]);
          }
          if (obs.t > 0.2 && obs.t < 1.98) {
            baseWindAcc.x += 0.08 * (wAcc.x - baseWindAcc.x);
            baseWindAcc.z += 0.08 * (wAcc.z - baseWindAcc.z);
          } else if (obs.t >= 1.98) {
            const gDelta = hypot2(wFast.x - baseWindAcc.x, wFast.z - baseWindAcc.z);
            if (gDelta < 1.0) {
              baseWindAcc.x += 0.015 * (wAcc.x - baseWindAcc.x);
              baseWindAcc.z += 0.015 * (wAcc.z - baseWindAcc.z);
            }
          }
        } else {
          vHat.x = v.x;
          vHat.z = v.z;
        }
      } else {
        vyHat = v.y;
        vHat.x = v.x;
        vHat.z = v.z;
      }

      const gustVecX = obs.t >= 1.98 ? wFast.x - baseWindAcc.x : 0;
      const gustVecZ = obs.t >= 1.98 ? wFast.z - baseWindAcc.z : 0;
      const gustMag = hypot2(gustVecX, gustVecZ);
      const gustTransient = hypot2(wFast.x - wAcc.x, wFast.z - wAcc.z);
      const gustActive = gustMag > 1.35 || gustTransient > 1.05;

      const cDrag = 0.0275 * thrustScale;
      let axDes = 0, ayDes = 0, azDes = 0;

      if (obs.gateIndex < 3) {
        padPinned = false;
        const gate = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'align';
          centeredCount = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = gate.y - p.y;
        const dzGate = gate.z - p.z;

        const dtLook = clamp(dxGate / Math.max(0.55, v.x + 0.55), 0.10, 0.22);
        const zPred = p.z + v.z * dtLook;
        const yPred = p.y + v.y * dtLook;
        const ezNow = Math.abs(dzGate);
        const eyNow = Math.abs(dyGate);
        const ezPred = Math.abs(gate.z - zPred);
        const eyPred = Math.abs(gate.y - yPred);

        const timeUrgent = obs.t > 10.2;
        const zTol = timeUrgent ? 0.020 : 0.014;
        const yTol = timeUrgent ? 0.072 : 0.050;
        const vzTol = timeUrgent ? 0.12 : 0.075;
        const vyTol = timeUrgent ? 0.20 : 0.14;

        // Conservative stopping position in x
        const xStop = p.x + v.x * 0.22 + (v.x > 0 ? (v.x * v.x) / 4.6 : 0);

        if (phase === 'align') {
          const latAligned = ezNow < 0.032 && eyNow < 0.08 && Math.abs(v.z) < 0.18;
          const baseStandOff = latAligned ? (gustActive ? 0.27 : 0.22) : (gustActive ? 0.38 : 0.33);
          const xStandOff = baseStandOff + clamp(0.42 * Math.max(0, ezNow - 0.035), 0, 0.25);
          const tx = gate.x - xStandOff;
          let tz = gate.z;
          let ty = gate.y;

          // Keep clear of previous gate frame right after crossing it
          if (obs.gateIndex > 0) {
            const prevG = GATE_LIST[obs.gateIndex - 1];
            if (p.x < prevG.x + 0.08) {
              tz = prevG.z;
              ty = prevG.y;
            }
          }

          const closeX = p.x > gate.x - 0.34 && p.x < gate.x - 0.06;
          const gustLatShock = Math.abs(wFast.z - wAcc.z);
          const isCentered = closeX && ezNow < zTol && ezPred < zTol + 0.003 &&
            eyNow < yTol && eyPred < yTol + 0.008 &&
            Math.abs(v.z) < vzTol && Math.abs(v.y) < vyTol &&
            (timeUrgent ? gustLatShock < 1.0 : (gustTransient < 0.68 && gustLatShock < 0.52));

          if (isCentered) centeredCount++;
          else centeredCount = Math.max(0, centeredCount - 1);

          const neededCount = timeUrgent ? 3 : 5;
          if (centeredCount >= neededCount) {
            phase = 'lunge';
          } else {
            const tailwind = Math.max(0, wFast.x);
            const vxCap = clamp((gustActive ? 0.55 : 0.80) - 0.08 * tailwind, 0.38, 0.80);
            const vxDes = clamp(1.30 * (tx - p.x), -0.95, vxCap);
            axDes = 4.5 * (vxDes - v.x);

            // Prevent backing into previous gate right after crossing
            if (obs.gateIndex > 0) {
              const prevG = GATE_LIST[obs.gateIndex - 1];
              if (p.x < prevG.x + 0.18) {
                axDes = Math.max(axDes, 5.0 * (0.55 - v.x));
              }
            }

            // Gate plane barrier: never drift across gate.x while uncentered
            if (xStop > gate.x - 0.11) {
              axDes = Math.min(axDes, -7.2 * (xStop - (gate.x - 0.11)) - 5.2 * Math.max(0, v.x));
            }
            const vzDes = clamp(1.65 * (tz - p.z), -1.15, 1.15);
            azDes = 4.9 * (vzDes - v.z);

            const vyDes = clamp(1.60 * (ty - p.y), -1.15, 1.15);
            ayDes = 4.7 * (vyDes - v.y);
          }
        }

        if (phase === 'lunge') {
          const dtCross = clamp(dxGate / Math.max(0.45, v.x + 0.45), 0.02, 0.26);
          const zAtCross = Math.abs(dzGate - v.z * dtCross);
          const yAtCross = Math.abs(dyGate - v.y * dtCross);
          const canStop = xStop < gate.x - 0.035 && dxGate > 0.11 && v.x < 0.65;

          if (canStop && (zAtCross > 0.024 || yAtCross > 0.10)) {
            phase = 'align';
            centeredCount = 0;
            axDes = -6.8 * Math.max(0, v.x) + 4.5 * ((gate.x - 0.26) - p.x);
            azDes = 9.5 * dzGate - 5.6 * v.z;
            ayDes = 8.2 * dyGate - 4.8 * v.y;
          } else {
            const vxLunge = obs.gateIndex === 2 ? 0.95 : 1.18;
            axDes = 5.4 * (vxLunge - v.x) + 1.4;
            azDes = 11.2 * dzGate - 6.2 * v.z;
            ayDes = 8.8 * dyGate - 5.0 * v.y;
          }
        }
      } else {
        // Gate 3 passed -> fly to pad and land
        const pad = obs.pad.centre;
        const dxPad = pad.x - p.x;
        const dzPad = pad.z - p.z;
        const distH = hypot2(dxPad, dzPad);
        const speedH = hypot2(v.x, v.z);
        const speed3 = hypot3(v.x, v.y, v.z);

        if (padPinned) {
          if (distH > 0.145 || p.y > 0.094) {
            padPinned = false;
          }
        } else {
          if (distH < 0.132 && p.y <= 0.091 && speed3 < 0.45 && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < 0.175) {
            padPinned = true;
          }
        }

        if (padPinned) {
          const axPin = clamp(4.0 * dxPad - 3.0 * v.x - wAcc.x, -1.1, 1.1);
          const azPin = clamp(4.0 * dzPad - 3.0 * v.z - wAcc.z, -1.1, 1.1);
          const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
          const pitchDes = clamp((cy * axPin - sy * azPin) / 9.81, -0.10, 0.10);
          const rollDes = clamp(-(sy * axPin + cy * azPin) / 9.81, -0.10, 0.10);
          const thrustCmd = 0.01;

          const alphaRoll = 75 * (rollDes - att.roll) - 15 * rates.roll;
          const alphaPitch = 75 * (pitchDes - att.pitch) - 15 * rates.pitch;
          const alphaYaw = -24 * att.yaw - 8 * rates.yaw;

          const rollCmd = clamp(att.roll + (alphaRoll + 13.4 * rates.roll - 22 * simInt.roll - kBias.roll * thrustCmd - fastBias.roll) / 65, -0.14, 0.14);
          const pitchCmd = clamp(att.pitch + (alphaPitch + 13.4 * rates.pitch - 22 * simInt.pitch - kBias.pitch * thrustCmd - fastBias.pitch) / 65, -0.14, 0.14);
          const yawRateCmd = clamp(rates.yaw + (alphaYaw + 0.4 * rates.yaw - kBias.yaw * thrustCmd) / 8, -2, 2);

          prevRollDes = rollDes;
          prevPitchDes = pitchDes;
          lastAction = { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
          prevObs = obs;
          return lastAction;
        }

        let ty = clamp(0.04 + 0.65 * Math.max(0, distH - 0.10), 0.04, 0.90);
        if (distH < 0.16 && speedH < 0.40) ty = 0.03;
        if (obs.t > 13.2 && distH < 0.20) ty = 0.03;

        const vxDes = clamp(1.25 * dxPad, -0.95, 0.95);
        const vzDes = clamp(1.25 * dzPad, -0.95, 0.95);
        axDes = 4.6 * (vxDes - v.x);
        azDes = 4.6 * (vzDes - v.z);

        // Prevent backing into Gate 2 right after crossing
        if (p.x < 1.35 + 0.16) {
          axDes = Math.max(axDes, 5.0 * (0.45 - v.x));
        }

        const ey = ty - p.y;
        const vyTarget = clamp(2.8 * ey, p.y < 0.22 ? -0.42 : -0.75, 1.0);
        ayDes = 6.0 * (vyTarget - v.y);
      }

      // Brake gusts & room boundary protection
      if (gustActive && phase !== 'lunge') {
        axDes -= 0.75 * v.x;
        azDes -= 0.75 * v.z;
      }
      if (p.x < -2.48 && v.x < 0) axDes = Math.max(axDes, -5.8 * v.x + 4.8 * (-2.48 - p.x));
      if (p.x > 2.48 && v.x > 0) axDes = Math.min(axDes, -5.8 * v.x + 4.8 * (2.48 - p.x));
      if (p.z < -2.48 && v.z < 0) azDes = Math.max(azDes, -5.8 * v.z + 4.8 * (-2.48 - p.z));
      if (p.z > 2.48 && v.z > 0) azDes = Math.min(azDes, -5.8 * v.z + 4.8 * (2.48 - p.z));
      if (p.y > 2.65 && v.y > 0) ayDes = Math.min(ayDes, -6.0 * v.y + 5.0 * (2.65 - p.y));

      // Cancel linear drag and observed wind acceleration (higher fast weight during lunge/gust)
      const fastWeight = (phase === 'lunge' || gustActive) ? 0.72 : 0.50;
      const wCtrlX = wAcc.x + fastWeight * (wFast.x - wAcc.x);
      const wCtrlZ = wAcc.z + fastWeight * (wFast.z - wAcc.z);
      const axThrust = clamp(axDes + cDrag * v.x - wCtrlX, -6.2, 6.2);
      const azThrust = clamp(azDes + cDrag * v.z - wCtrlZ, -6.2, 6.2);
      const ayThrust = clamp(9.81 + ayDes + cDrag * v.y, 1.5, 16.0);

      const dirY = Math.max(0.52, Math.cos(att.roll) * Math.cos(att.pitch));
      const thrustCmd = clamp(ayThrust / (thrustScale * dirY), 0.05, 0.84);

      // Desired attitude from desired thrust vector (axThrust, ayThrust, azThrust)
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bx = cy * axThrust - sy * azThrust;
      const bz = sy * axThrust + cy * azThrust;
      const maxTilt = (obs.gateIndex === 3 && p.y < 0.18 && hypot2(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.16) ? 0.15 : 0.56;
      const pitchDes = clamp(Math.atan2(bx, ayThrust), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(bz, Math.hypot(bx, ayThrust)), -maxTilt, maxTilt);

      const rollRateDes = prevObs ? clamp((rollDes - prevRollDes) / dt, -3.0, 3.0) : 0;
      const pitchRateDes = prevObs ? clamp((pitchDes - prevPitchDes) / dt, -3.0, 3.0) : 0;
      prevRollDes = rollDes;
      prevPitchDes = pitchDes;

      // Invert inner attitude loop with torque bias
      const alphaRoll = 100 * (rollDes - att.roll) + 18 * (0.35 * rollRateDes - rates.roll);
      const alphaPitch = 100 * (pitchDes - att.pitch) + 18 * (0.35 * pitchRateDes - rates.pitch);
      const alphaYaw = -28 * att.yaw - 9 * rates.yaw;

      const rollCmd = clamp(att.roll + (alphaRoll + 13.4 * rates.roll - 22 * simInt.roll - kBias.roll * thrustCmd - fastBias.roll) / 65, -0.6, 0.6);
      const pitchCmd = clamp(att.pitch + (alphaPitch + 13.4 * rates.pitch - 22 * simInt.pitch - kBias.pitch * thrustCmd - fastBias.pitch) / 65, -0.6, 0.6);
      const yawRateCmd = clamp(rates.yaw + (alphaYaw + 0.4 * rates.yaw - kBias.yaw * thrustCmd) / 8, -2, 2);

      lastAction = { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
      prevObs = obs;
      return lastAction;
    },
  };
}

const GATE_LIST = [
  { x: -1.15, y: 1.05, z: -0.85 },
  { x: 0.15, y: 1.40, z: 0.25 },
  { x: 1.35, y: 1.05, z: 1.05 },
];

export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const hypot2 = (x, z) => Math.hypot(x, z);
  const hypot3 = (x, y, z) => Math.hypot(x, y, z);

  let prevObs = null;
  let lastAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };
  let simInt = { roll: 0, pitch: 0 };
  let uEff = { roll: 0, pitch: 0, yaw: 0 };
  let thrustEff = 0.5;

  // Torque bias observer (per unit thrust + fast residual)
  let kBias = { roll: 0, pitch: 0, yaw: 0 };
  let fastBias = { roll: 0, pitch: 0 };

  // Thrust scale observer: effective (maxThrustSum / mass), nominal ~20.0
  let thrustScale = 20.0;
  let vyHat = 0;

  // Wind acceleration observers (m/s^2)
  let vHat = { x: 0, z: 0 };
  let wAcc = { x: 0, z: 0 };
  let wFast = { x: 0, z: 0 };
  let baseWindAcc = { x: 0, z: 0 };

  // Navigation state
  let targetGate = -1;
  let phase = 'align';
  let centeredCount = 0;
  let padPinned = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos;
      const v = obs.vel;
      const att = obs.att;
      const rates = obs.rates;

      if (prevObs !== null) {
        const alphaLag = 0.23; // ~0.038s motor lag
        for (const axis of ['roll', 'pitch']) {
          const e1 = lastAction[axis] - prevObs.att[axis];
          simInt[axis] = clamp(simInt[axis] + e1 * 0.005, -0.35, 0.35);
          const u1 = 65 * e1 - 13 * prevObs.rates[axis] + 22 * simInt[axis];

          const attMid = 0.5 * (prevObs.att[axis] + att[axis]);
          const rateMid = 0.5 * (prevObs.rates[axis] + rates[axis]);
          const e2 = lastAction[axis] - attMid;
          simInt[axis] = clamp(simInt[axis] + e2 * 0.005, -0.35, 0.35);
          const u2 = 65 * e2 - 13 * rateMid + 22 * simInt[axis];

          const uCmd = 0.5 * (u1 + u2);
          uEff[axis] += (uCmd - uEff[axis]) * alphaLag;
        }
        const uYawCmd = 8 * (lastAction.yawRate - 0.5 * (prevObs.rates.yaw + rates.yaw));
        uEff.yaw += (uYawCmd - uEff.yaw) * alphaLag;
        thrustEff += (lastAction.thrust - thrustEff) * alphaLag;

        const airborne = p.y > 0.085 && prevObs.pos.y > 0.085 && p.y < 2.91;

        if (airborne && thrustEff > 0.12 && thrustEff < 0.82) {
          for (const axis of ['roll', 'pitch']) {
            if (Math.abs(lastAction[axis]) < 0.56) {
              const rateMid = 0.5 * (prevObs.rates[axis] + rates[axis]);
              const alphaMeas = (rates[axis] - prevObs.rates[axis]) / dt + 0.4 * rateMid;
              const res = alphaMeas - uEff[axis];
              const predBias = kBias[axis] * thrustEff;
              const err = clamp(res - predBias, -20, 20);
              const gain = 0.20 * thrustEff / (thrustEff * thrustEff + 0.04);
              kBias[axis] = clamp(kBias[axis] + gain * err, -25, 25);
              fastBias[axis] = clamp(fastBias[axis] + 0.07 * (res - kBias[axis] * thrustEff - fastBias[axis]), -5, 5);
            }
          }
          const rateYawMid = 0.5 * (prevObs.rates.yaw + rates.yaw);
          const alphaYawMeas = (rates.yaw - prevObs.rates.yaw) / dt + 0.4 * rateYawMid;
          const resYaw = alphaYawMeas - uEff.yaw;
          const errYaw = clamp(resYaw - kBias.yaw * thrustEff, -8, 8);
          kBias.yaw = clamp(kBias.yaw + 0.15 * thrustEff * errYaw / (thrustEff * thrustEff + 0.04), -6, 6);
        }

        const attR = 0.5 * (prevObs.att.roll + att.roll);
        const attP = 0.5 * (prevObs.att.pitch + att.pitch);
        const attY = 0.5 * (prevObs.att.yaw + att.yaw);
        const bodyX = Math.sin(attP) * Math.cos(attR);
        const bodyZ = -Math.sin(attR);
        const dirX = Math.cos(attY) * bodyX + Math.sin(attY) * bodyZ;
        const dirY = Math.cos(attP) * Math.cos(attR);
        const dirZ = -Math.sin(attY) * bodyX + Math.cos(attY) * bodyZ;

        if (airborne) {
          const vyMid = 0.5 * (prevObs.vel.y + v.y);
          const uy = thrustEff * dirY - 0.0275 * vyMid;
          const vyPred = vyHat + (thrustScale * uy - 9.81) * dt;
          const errVy = v.y - vyPred;
          vyHat = vyPred + 0.42 * errVy;
          if (uy > 0.15 && thrustEff < 0.82) {
            thrustScale = clamp(thrustScale + 5.0 * errVy * uy, 14.8, 26.8);
          }
        } else {
          vyHat = v.y;
        }

        const clearWalls = Math.abs(p.x) < 2.81 && Math.abs(p.z) < 2.81;
        if (airborne && clearWalls) {
          const cDrag = 0.0275 * thrustScale;
          for (const axis of ['x', 'z']) {
            const dirA = axis === 'x' ? dirX : dirZ;
            const vMid = 0.5 * (prevObs.vel[axis] + v[axis]);
            const aKnown = thrustScale * thrustEff * dirA - cDrag * vMid;
            const vPred = vHat[axis] + (aKnown + wAcc[axis]) * dt;
            const errV = v[axis] - vPred;
            vHat[axis] = vPred + 0.46 * errV;
            wAcc[axis] = clamp(wAcc[axis] + 6.8 * errV, -8.5, 8.5);

            const aMeas = (v[axis] - prevObs.vel[axis]) / dt;
            const wInst = clamp(aMeas - aKnown, -10.5, 10.5);
            wFast[axis] += 0.35 * (wInst - wFast[axis]);
          }
          if (obs.t > 0.2 && obs.t < 1.98) {
            baseWindAcc.x += 0.08 * (wAcc.x - baseWindAcc.x);
            baseWindAcc.z += 0.08 * (wAcc.z - baseWindAcc.z);
          } else if (obs.t >= 1.98) {
            const gDelta = hypot2(wFast.x - baseWindAcc.x, wFast.z - baseWindAcc.z);
            if (gDelta < 1.0) {
              baseWindAcc.x += 0.015 * (wAcc.x - baseWindAcc.x);
              baseWindAcc.z += 0.015 * (wAcc.z - baseWindAcc.z);
            }
          }
        } else {
          vHat.x = v.x;
          vHat.z = v.z;
        }
      } else {
        vyHat = v.y;
        vHat.x = v.x;
        vHat.z = v.z;
      }

      const gustVecX = obs.t >= 1.98 ? wFast.x - baseWindAcc.x : 0;
      const gustVecZ = obs.t >= 1.98 ? wFast.z - baseWindAcc.z : 0;
      const gustMag = hypot2(gustVecX, gustVecZ);
      const gustTransient = hypot2(wFast.x - wAcc.x, wFast.z - wAcc.z);
      const gustActive = gustMag > 1.35 || gustTransient > 1.1;

      const cDrag = 0.0275 * thrustScale;
      let axDes = 0, ayDes = 0, azDes = 0;

      if (obs.gateIndex < 3) {
        padPinned = false;
        const gate = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'align';
          centeredCount = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = gate.y - p.y;
        const dzGate = gate.z - p.z;

        const zPred = p.z + v.z * 0.16;
        const yPred = p.y + v.y * 0.16;
        const ezNow = Math.abs(dzGate);
        const eyNow = Math.abs(dyGate);
        const ezPred = Math.abs(gate.z - zPred);
        const eyPred = Math.abs(gate.y - yPred);

        const timeUrgent = obs.t > 10.2;
        const zTol = timeUrgent ? 0.021 : 0.014;
        const yTol = timeUrgent ? 0.075 : 0.052;
        const vzTol = timeUrgent ? 0.13 : 0.080;
        const vyTol = timeUrgent ? 0.22 : 0.15;

        const xStop = p.x + v.x * 0.22 + (v.x > 0 ? (v.x * v.x) / 4.6 : 0);

        if (phase === 'align') {
          const latNear = ezNow < 0.032 && eyNow < 0.075;
          const baseStandOff = latNear ? (gustActive ? 0.30 : 0.24) : (gustActive ? 0.37 : 0.31);
          const xStandOff = baseStandOff + clamp(0.42 * Math.max(0, ezNow - 0.04), 0, 0.24);
          const tx = gate.x - xStandOff;
          let tz = gate.z;
          let ty = gate.y;

          if (obs.gateIndex > 0) {
            const prevG = GATE_LIST[obs.gateIndex - 1];
            if (p.x < prevG.x + 0.07) {
              tz = prevG.z;
              ty = prevG.y;
            }
          }

          const vzDes = clamp(1.6 * (tz - p.z), -1.15, 1.15);
          azDes = 4.8 * (vzDes - v.z);

          const vyDes = clamp(1.6 * (ty - p.y), -1.15, 1.15);
          ayDes = 4.6 * (vyDes - v.y);

          const closeX = p.x > gate.x - 0.38 && p.x < gate.x - 0.06;
          const latSteady = timeUrgent || Math.abs(azDes) < 1.1;
          const isCentered = closeX && ezNow < zTol && ezPred < zTol + 0.004 &&
            eyNow < yTol && eyPred < yTol + 0.01 &&
            Math.abs(v.z) < vzTol && Math.abs(v.y) < vyTol &&
            latSteady && (!gustActive || timeUrgent || gustTransient < 0.72);

          if (isCentered) centeredCount++;
          else centeredCount = Math.max(0, centeredCount - 1);

          const neededCount = timeUrgent ? 3 : 5;
          if (centeredCount >= neededCount) {
            phase = 'lunge';
          } else {
            const tailwind = Math.max(0, wFast.x);
            const vxCap = clamp((gustActive ? 0.58 : 0.84) - 0.07 * tailwind, 0.40, 0.84);
            const vxDes = clamp(1.25 * (tx - p.x), -0.95, vxCap);
            axDes = 4.3 * (vxDes - v.x);

            if (obs.gateIndex > 0) {
              const prevG = GATE_LIST[obs.gateIndex - 1];
              if (p.x < prevG.x + 0.16) {
                axDes = Math.max(axDes, 5.0 * (0.50 - v.x));
              }
            }

            // Gate plane barrier: never drift across gate.x while uncentered
            if (xStop > gate.x - 0.11) {
              axDes = Math.min(axDes, -7.0 * (xStop - (gate.x - 0.11)) - 5.2 * Math.max(0, v.x));
            }
          }
        }

        if (phase === 'lunge') {
          const dtCross = clamp(dxGate / Math.max(0.42, v.x + 0.42), 0.02, 0.28);
          const zAtCross = Math.abs(dzGate - v.z * dtCross);
          const yAtCross = Math.abs(dyGate - v.y * dtCross);
          const canStop = xStop < gate.x - 0.04 && dxGate > 0.12 && v.x < 0.65;

          if (canStop && (zAtCross > 0.025 || yAtCross > 0.105)) {
            phase = 'align';
            centeredCount = 0;
            axDes = -6.5 * Math.max(0, v.x) + 4.5 * ((gate.x - 0.28) - p.x);
            azDes = 9.0 * dzGate - 5.4 * v.z;
            ayDes = 8.0 * dyGate - 4.8 * v.y;
          } else {
            const tx = gate.x + 0.30;
            const vxLungeCap = obs.gateIndex === 2 ? 0.98 : 1.25;
            axDes = clamp(5.8 * (tx - p.x) - 3.4 * v.x + 1.8, -6.0, 5.0 * (vxLungeCap - v.x) + 1.8);
            azDes = 11.2 * dzGate - 6.0 * v.z;
            ayDes = 8.5 * dyGate - 4.8 * v.y;
          }
        }
      } else {
        // Gate 3 passed -> fly to pad and land
        const pad = obs.pad.centre;
        const dxPad = pad.x - p.x;
        const dzPad = pad.z - p.z;
        const distH = hypot2(dxPad, dzPad);
        const speedH = hypot2(v.x, v.z);
        const speed3 = hypot3(v.x, v.y, v.z);

        if (padPinned) {
          if (distH > 0.145 || p.y > 0.094) {
            padPinned = false;
          }
        } else {
          if (distH < 0.130 && p.y <= 0.091 && speed3 < 0.45 && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < 0.175) {
            padPinned = true;
          }
        }

        if (padPinned) {
          const axPin = clamp(4.0 * dxPad - 3.0 * v.x - wAcc.x, -1.1, 1.1);
          const azPin = clamp(4.0 * dzPad - 3.0 * v.z - wAcc.z, -1.1, 1.1);
          const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
          const pitchDes = clamp((cy * axPin - sy * azPin) / 9.81, -0.10, 0.10);
          const rollDes = clamp(-(sy * axPin + cy * azPin) / 9.81, -0.10, 0.10);
          const thrustCmd = 0.01;

          const alphaRoll = 75 * (rollDes - att.roll) - 15 * rates.roll;
          const alphaPitch = 75 * (pitchDes - att.pitch) - 15 * rates.pitch;
          const alphaYaw = -24 * att.yaw - 8 * rates.yaw;

          const rollCmd = clamp(att.roll + (alphaRoll + 13.4 * rates.roll - 22 * simInt.roll - kBias.roll * thrustCmd - fastBias.roll) / 65, -0.14, 0.14);
          const pitchCmd = clamp(att.pitch + (alphaPitch + 13.4 * rates.pitch - 22 * simInt.pitch - kBias.pitch * thrustCmd - fastBias.pitch) / 65, -0.14, 0.14);
          const yawRateCmd = clamp(rates.yaw + (alphaYaw + 0.4 * rates.yaw - kBias.yaw * thrustCmd) / 8, -2, 2);

          lastAction = { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
          prevObs = obs;
          return lastAction;
        }

        // Stay safely above floor (y >= 0.26) until horizontally near pad (distH < 0.16)
        let ty = clamp(0.24 + 0.55 * Math.max(0, distH - 0.14), 0.24, 0.90);
        if (distH < 0.15 && speedH < 0.42) ty = 0.03;
        else if (distH < 0.12 && speedH < 0.55) ty = 0.04;
        if (obs.t > 13.0 && distH < 0.19) ty = 0.03;

        const vxDes = clamp(1.25 * dxPad, -0.95, 0.95);
        const vzDes = clamp(1.25 * dzPad, -0.95, 0.95);
        axDes = 4.5 * (vxDes - v.x);
        azDes = 4.5 * (vzDes - v.z);

        if (p.x < 1.35 + 0.16) {
          axDes = Math.max(axDes, 5.0 * (0.45 - v.x));
        }

        const ey = ty - p.y;
        const vyTarget = clamp(2.8 * ey, p.y < 0.22 ? -0.40 : -0.75, 1.0);
        ayDes = 6.0 * (vyTarget - v.y);
      }

      // Brake gusts & room boundary protection
      if (gustActive && phase !== 'lunge') {
        axDes -= 0.7 * v.x;
        azDes -= 0.7 * v.z;
      }
      if (p.x < -2.40 && v.x < 0) axDes = Math.max(axDes, -5.8 * v.x + 5.0 * (-2.40 - p.x));
      if (p.x > 2.38 && v.x > 0) axDes = Math.min(axDes, -5.8 * v.x + 5.0 * (2.38 - p.x));
      if (p.z < -2.40 && v.z < 0) azDes = Math.max(azDes, -5.8 * v.z + 5.0 * (-2.40 - p.z));
      if (p.z > 2.38 && v.z > 0) azDes = Math.min(azDes, -5.8 * v.z + 5.0 * (2.38 - p.z));
      if (p.y > 2.65 && v.y > 0) ayDes = Math.min(ayDes, -6.0 * v.y + 5.0 * (2.65 - p.y));

      // Cancel linear drag and observed wind acceleration
      const wCtrlX = wAcc.x + 0.48 * (wFast.x - wAcc.x);
      const wCtrlZ = wAcc.z + 0.48 * (wFast.z - wAcc.z);
      const axThrust = clamp(axDes + cDrag * v.x - wCtrlX, -6.2, 6.2);
      const azThrust = clamp(azDes + cDrag * v.z - wCtrlZ, -6.2, 6.2);
      const ayThrust = clamp(9.81 + ayDes + cDrag * v.y, 1.5, 16.0);

      const dirY = Math.max(0.52, Math.cos(att.roll) * Math.cos(att.pitch));
      const thrustCmd = clamp(ayThrust / (thrustScale * dirY), 0.05, 0.84);

      // Desired attitude from desired thrust vector (axThrust, ayThrust, azThrust)
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bx = cy * axThrust - sy * azThrust;
      const bz = sy * axThrust + cy * azThrust;
      let maxTilt = 0.55;
      if (p.y < 0.22) maxTilt = 0.28;
      if (obs.gateIndex === 3 && p.y < 0.18 && hypot2(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.16) maxTilt = 0.15;
      const pitchDes = clamp(Math.atan2(bx, ayThrust), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(bz, Math.hypot(bx, ayThrust)), -maxTilt, maxTilt);

      // Invert inner attitude loop with torque bias
      const alphaRoll = 95 * (rollDes - att.roll) - 18 * rates.roll;
      const alphaPitch = 95 * (pitchDes - att.pitch) - 18 * rates.pitch;
      const alphaYaw = -28 * att.yaw - 9 * rates.yaw;

      const rollCmd = clamp(att.roll + (alphaRoll + 13.4 * rates.roll - 22 * simInt.roll - kBias.roll * thrustCmd - fastBias.roll) / 65, -0.6, 0.6);
      const pitchCmd = clamp(att.pitch + (alphaPitch + 13.4 * rates.pitch - 22 * simInt.pitch - kBias.pitch * thrustCmd - fastBias.pitch) / 65, -0.6, 0.6);
      const yawRateCmd = clamp(rates.yaw + (alphaYaw + 0.4 * rates.yaw - kBias.yaw * thrustCmd) / 8, -2, 2);

      lastAction = { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate: yawRateCmd };
      prevObs = obs;
      return lastAction;
    },
  };
}

const GATE_LIST = [
  { x: -1.15, y: 1.05, z: -0.85 },
  { x: 0.15, y: 1.40, z: 0.25 },
  { x: 1.35, y: 1.05, z: 1.05 },
];

export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const hypot2 = (x, z) => Math.hypot(x, z);
  const hypot3 = (x, y, z) => Math.hypot(x, y, z);

  let prevObs = null;
  let lastAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };
  let simInt = { roll: 0, pitch: 0 };
  let uEff = { roll: 0, pitch: 0, yaw: 0 };
  let thrustEff = 0.5;

  // Torque bias observer (per unit thrust + fast residual)
  let kBias = { roll: 0, pitch: 0, yaw: 0 };
  let fastBias = { roll: 0, pitch: 0 };

  // Thrust scale observer: effective (maxThrustSum / mass), nominal ~20.0
  let thrustScale = 20.0;
  let vyHat = 0;

  // Wind acceleration observers (m/s^2)
  let vHat = { x: 0, z: 0 };
  let wAcc = { x: 0, z: 0 };
  let wFast = { x: 0, z: 0 };
  let baseWindAcc = { x: 0, z: 0 };

  // Navigation state
  let targetGate = -1;
  let phase = 'align';
  let centeredCount = 0;
  let padPinned = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos;
      const v = obs.vel;
      const att = obs.att;
      const rates = obs.rates;

      if (prevObs !== null) {
        const alphaLag = 0.23; // ~0.038s motor lag
        for (const axis of ['roll', 'pitch']) {
          const e1 = lastAction[axis] - prevObs.att[axis];
          simInt[axis] = clamp(simInt[axis] + e1 * 0.005, -0.35, 0.35);
          const u1 = 65 * e1 - 13 * prevObs.rates[axis] + 22 * simInt[axis];

          const attMid = 0.5 * (prevObs.att[axis] + att[axis]);
          const rateMid = 0.5 * (prevObs.rates[axis] + rates[axis]);
          const e2 = lastAction[axis] - attMid;
          simInt[axis] = clamp(simInt[axis] + e2 * 0.005, -0.35, 0.35);
          const u2 = 65 * e2 - 13 * rateMid + 22 * simInt[axis];

          const uCmd = 0.5 * (u1 + u2);
          uEff[axis] += (uCmd - uEff[axis]) * alphaLag;
        }
        const uYawCmd = 8 * (lastAction.yawRate - 0.5 * (prevObs.rates.yaw + rates.yaw));
        uEff.yaw += (uYawCmd - uEff.yaw) * alphaLag;
        thrustEff += (lastAction.thrust - thrustEff) * alphaLag;

        const airborne = p.y > 0.085 && prevObs.pos.y > 0.085 && p.y < 2.91;

        if (airborne && thrustEff > 0.12 && thrustEff < 0.82) {
          for (const axis of ['roll', 'pitch']) {
            if (Math.abs(lastAction[axis]) < 0.56) {
              const rateMid = 0.5 * (prevObs.rates[axis] + rates[axis]);
              const alphaMeas = (rates[axis] - prevObs.rates[axis]) / dt + 0.4 * rateMid;
              const res = alphaMeas - uEff[axis];
              const predBias = kBias[axis] * thrustEff;
              const err = clamp(res - predBias, -20, 20);
              const gain = 0.20 * thrustEff / (thrustEff * thrustEff + 0.04);
              kBias[axis] = clamp(kBias[axis] + gain * err, -25, 25);
              fastBias[axis] = clamp(fastBias[axis] + 0.07 * (res - kBias[axis] * thrustEff - fastBias[axis]), -5, 5);
            }
          }
          const rateYawMid = 0.5 * (prevObs.rates.yaw + rates.yaw);
          const alphaYawMeas = (rates.yaw - prevObs.rates.yaw) / dt + 0.4 * rateYawMid;
          const resYaw = alphaYawMeas - uEff.yaw;
          const errYaw = clamp(resYaw - kBias.yaw * thrustEff, -8, 8);
          kBias.yaw = clamp(kBias.yaw + 0.15 * thrustEff * errYaw / (thrustEff * thrustEff + 0.04), -6, 6);
        }

        const attR = 0.5 * (prevObs.att.roll + att.roll);
        const attP = 0.5 * (prevObs.att.pitch + att.pitch);
        const attY = 0.5 * (prevObs.att.yaw + att.yaw);
        const bodyX = Math.sin(attP) * Math.cos(attR);
        const bodyZ = -Math.sin(attR);
        const dirX = Math.cos(attY) * bodyX + Math.sin(attY) * bodyZ;
        const dirY = Math.cos(attP) * Math.cos(attR);
        const dirZ = -Math.sin(attY) * bodyX + Math.cos(attY) * bodyZ;

        if (airborne) {
          const vyMid = 0.5 * (prevObs.vel.y + v.y);
          const uy = thrustEff * dirY - 0.0275 * vyMid;
          const vyPred = vyHat + (thrustScale * uy - 9.81) * dt;
          const errVy = v.y - vyPred;
          vyHat = vyPred + 0.42 * errVy;
          if (uy > 0.15 && thrustEff < 0.82) {
            thrustScale = clamp(thrustScale + 5.0 * errVy * uy, 14.8, 26.8);
          }
        } else {
          vyHat = v.y;
        }

        const clearWalls = Math.abs(p.x) < 2.81 && Math.abs(p.z) < 2.81;
        if (airborne && clearWalls) {
          const cDrag = 0.0275 * thrustScale;
          for (const axis of ['x', 'z']) {
            const dirA = axis === 'x' ? dirX : dirZ;
            const vMid = 0.5 * (prevObs.vel[axis] + v[axis]);
            const aKnown = thrustScale * thrustEff * dirA - cDrag * vMid;
            const vPred = vHat[axis] + (aKnown + wAcc[axis]) * dt;
            const errV = v[axis] - vPred;
            vHat[axis] = vPred + 0.46 * errV;
            wAcc[axis] = clamp(wAcc[axis] + 6.8 * errV, -8.5, 8.5);

            const aMeas = (v[axis] - prevObs.vel[axis]) / dt;
            const wInst = clamp(aMeas - aKnown, -10.5, 10.5);
            wFast[axis] += 0.35 * (wInst - wFast[axis]);
          }
          if (obs.t > 0.2 && obs.t < 1.98) {
            baseWindAcc.x += 0.08 * (wAcc.x - baseWindAcc.x);
            baseWindAcc.z += 0.08 * (wAcc.z - baseWindAcc.z);
          } else if (obs.t >= 1.98) {
            const gDelta = hypot2(wFast.x - baseWindAcc.x, wFast.z - baseWindAcc.z);
            if (gDelta < 1.0) {
              baseWindAcc.x += 0.015 * (wAcc.x - baseWindAcc.x);
              baseWindAcc.z += 0.015 * (wAcc.z - baseWindAcc.z);
