            centeredCount = 0;
            axDes = -7.8 * Math.max(0, v.x) + 4.5 * ((gate.x - 0.30) - p.x);
            azDes = 10.5 * dzGate - 5.8 * v.z;
            ayDes = 8.0 * dyGate - 4.8 * v.y;
          } else {
            const tx = gate.x + 0.34;
            const vxLungeCap = obs.gateIndex === 2 ? 1.12 : 1.40;
            axDes = clamp(6.2 * (tx - p.x) - 3.4 * v.x + 2.1, -6.0, 5.5 * (vxLungeCap - v.x) + 2.1);
